async function api<T>(path:string,method='GET',body?:unknown):Promise<T>{
  let res:Response;
  try{res=await fetch('/api'+path,{method,headers:body instanceof FormData?undefined:body?{'Content-Type':'application/json'}:undefined,body:body instanceof FormData?body:body?JSON.stringify(body):undefined})}
  catch{throw new Error('无法连接本地服务。请运行“启动.cmd”，然后重试连接。')}
  if(!res.ok){let message=res.statusText;try{const e=await res.json();message=typeof e.detail==='string'?e.detail:JSON.stringify(e.detail)}catch{}throw new Error(message)}
  return res.json();
}
