function useImage(url:string|undefined){const [image,setImage]=useState<HTMLImageElement>();useEffect(()=>{setImage(undefined);if(!url)return;let active=true;const i=new window.Image();i.onload=()=>{if(active)setImage(i)};i.src=url;return()=>{active=false}},[url]);return image}
function Bitmap({url,width,height,opacity=1}:{url:string;width:number;height:number;opacity?:number}){const img=useImage(url);return <KImage image={img} width={width} height={height} opacity={opacity}/>}
function IconButton({label,children,...props}:React.ButtonHTMLAttributes<HTMLButtonElement>&{label:string}){return <button {...props} title={label} aria-label={label} className={'icon-button '+(props.className||'')}>{children}</button>}

