 const upload=async(file?:File)=>{if(!file)return;setBusy(true);setError('');try{await saveNow();const f=new FormData();f.append('file',file);const p=await api<Project>('/projects','POST',f);projectRef.current=p.id;setProject(p);setPages(p.pages.map(x=>x.index));loadPage(p.pages[0]);refresh()}catch(e){catchError(e)}finally{setBusy(false);if(input.current)input.current.value=''}};
 const startJob=async(path:string,payload:unknown)=>{await saveNow();if(dirty.current)await saveNow();const r=await api<{id:string}>(path,'POST',payload);setJob({id:r.id,status:'queued',progress:0,message:'排队中'});setTool('select');setGesture([]);setArea(null);return r.id};
