 const update=(updates:Partial<LayerElement>,ids=selected)=>{
   if(!scene)return;
   const editsText=['text','font','font_size','bold','italic','char_spacing','text_fit'].some(key=>key in updates);
   const onlyState=Object.keys(updates).every(key=>['locked','visible','needs_review'].includes(key));
   commit({...scene,layers:scene.layers.map(l=>{
     if(!ids.includes(l.id)||(l.locked&&!onlyState))return l;
     if(updates.text_fit!==undefined&&l.kind!=='text')return l;
     let next={...l,...updates,edited:true};
     if(editsText||next.stroke||next.text_shadow||next.text_gradient?.length)next.text_layout=null;
     if(l.font_asset&&((updates.font!==undefined&&updates.font!==l.font)||(updates.text!==undefined&&Array.from(updates.text).some(char=>!l.font_asset!.characters.includes(char))))){
       next.font_asset=null;
       if(updates.font===undefined){next.font='Microsoft YaHei';setInfo('新文字已切换为微软雅黑；还原字形保留在撤销历史中')}
     }
     if(next.text_fit==='shape'&&/[\r\n]/.test(next.text))next.text_fit='natural';
     if(next.text_fit==='shape'&&l.text_fit==='shape'&&updates.font_size!==undefined){
       const ratio=next.font_size/l.font_size;
       next.width=Math.min(50000,l.width*ratio);next.height=Math.min(50000,l.height*ratio);
     }
     if(next.kind==='text'&&editsText){
       const context=document.createElement('canvas').getContext('2d');
       if(context){context.font=`${next.italic?'italic ':''}${next.bold?'bold ':''}${next.font_size}px ${JSON.stringify(next.font)}`;next=fitTextBounds(next,text=>context.measureText(text).width)}
     }
     return next;
   })});
 };
