 useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.target as HTMLElement).closest('input,textarea,select')||disabled)return;if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redoAction():undoAction()}else if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();saveNow().catch(()=>{})}else if(e.key==='Delete')remove();else if(e.key==='Escape'){if(focusCanvas){setFocusCanvas(false);return}setSelected([]);setTool('select');setArea(null)}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)});
