 const selectLayer=(l:LayerElement,shift=false)=>{if(tool!=='select')return;const ids=l.group_id?scene!.layers.filter(x=>x.group_id===l.group_id).map(x=>x.id):[l.id];setSelected(prev=>shift?Array.from(new Set([...prev,...ids])):ids)};
 const transformEnd=()=>{if(!scene||!stageRef.current)return;const next=copy(scene);next.layers=next.layers.map(l=>{
   if(!selected.includes(l.id)||l.locked)return l;const n=stageRef.current!.findOne('#'+l.id);if(!n)return l;
   const sx=n.scaleX(),sy=n.scaleY();const updated={...l,x:n.x(),y:n.y(),width:Math.max(.1,l.width*sx),height:Math.max(.1,l.height*sy),rotation:n.rotation(),edited:true};
   if(l.kind==='path')updated.path=l.path.map(c=>({...c,points:c.points.map((v,i)=>v*(i%2?sy:sx))}));
   if(l.kind==='text'){updated.font_size=l.font_size*Math.min(sx,sy);updated.char_spacing=(l.char_spacing||0)*Math.min(sx,sy);if(updated.font_size!==l.font_size||updated.char_spacing!==(l.char_spacing||0))updated.text_layout=null}
   n.scale({x:1,y:1});return updated;
 });commit(next)};
 const dragStart=useRef<{x:number;y:number}|null>(null);
 const dragEnd=(l:LayerElement,n:Konva.Node)=>{if(!scene)return;const dx=n.x()-l.x,dy=n.y()-l.y;const ids=selected.includes(l.id)?selected:[l.id];commit({...scene,layers:scene.layers.map(v=>ids.includes(v.id)&&!v.locked?{...v,x:v.x+dx,y:v.y+dy,edited:true}:v)});dragStart.current=null};
 const group=()=>{if(selected.length<2||!scene)return;const id=crypto.randomUUID();const top=Math.max(...scene.layers.map(l=>l.z),0)+1;let offset=0;commit({...scene,layers:scene.layers.map(l=>selected.includes(l.id)?{...l,group_id:id,z:top+offset++*.01,edited:true}:l)})};
 const reorder=(direction:number)=>{if(!scene)return;const edge=(direction>0?Math.max(...scene.layers.map(l=>l.z)):Math.min(...scene.layers.map(l=>l.z)))+direction;let i=0;commit({...scene,layers:scene.layers.map(l=>selected.includes(l.id)?{...l,z:edge+i++*.001,edited:true}:l)})};
 const add=(kind:LayerElement['kind'])=>{if(!scene)return;const l=makeLayer(kind,Math.max(...scene.layers.map(x=>x.z),0)+1);commit({...scene,layers:[...scene.layers,l]});setSelected([l.id])};
 const exportFile=async()=>{setBusy(true);setExporting(true);setError('');try{await saveNow();const res=await fetch(`/api/projects/${project!.id}/${exportFormat==='docx'?'export-docx':'export'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pages})});if(!res.ok){let message='本地导出失败，项目已保留，请重试';try{message=(await res.json()).detail||message}catch{}throw new Error(message)}const u=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=u;a.download=project!.name.replace(/\.(pdf|png|jpe?g|webp|tiff?|bmp)$/i,'')+'-分层.'+exportFormat;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);let notice='';try{notice=decodeURIComponent(res.headers.get('X-LayerDeck-Notice')||'')}catch{notice='部分导出检查未完成，请核对文档'}setInfo((exportFormat==='docx'?'Word 已导出为可编辑文字与独立素材；待校正项仍需检查':'PPTX 已导出，待校正项仍保留在项目中')+(notice?'。'+notice:''))}catch(e){catchError(e)}finally{setBusy(false);setExporting(false)}};
 const fit=scene?Math.min((size.width-96)/scene.width,(size.height-96)/scene.height):1;const scale=Math.max(.05,fit*zoom);
 const offset=scene?{x:(size.width-scene.width*scale)/2,y:(size.height-scene.height*scale)/2}:{x:0,y:0};
 const pointer=()=>{if(!stageRef.current||!chosen)return null;const pos=stageRef.current.getPointerPosition();const node=stageRef.current.findOne('#'+chosen.id);if(!pos||!node)return null;const p=node.getAbsoluteTransform().copy().invert().point(pos);return [Math.max(0,Math.min(chosen.width,p.x)),Math.max(0,Math.min(chosen.height,p.y))]};
 const pointerDown=()=>{if(disabled||!chosen||chosen.kind!=='image'||tool==='select')return;const p=pointer();if(!p)return;drawing.current=true;setGesture([p]);setArea(null)};
 const pointerMove=()=>{if(!drawing.current)return;const p=pointer();if(p)setGesture(g=>tool==='brush'?[...g,p]:[g[0],p])};
 const pointerUp=()=>{if(!drawing.current)return;drawing.current=false;const p=pointer();if(!p||!gesture.length)return;const points=tool==='brush'?[...gesture,p]:[gesture[0],p];const xs=points.map(x=>x[0]),ys=points.map(x=>x[1]);setGesture(points);setArea({box:[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)],points})};
 const pixelArea=async()=>{if(!chosen?.asset||!project)throw new Error('请选择图片图层');const img=new window.Image();img.src=asset(project.id,chosen.asset);await img.decode();const sx=img.naturalWidth/chosen.width,sy=img.naturalHeight/chosen.height;return {box:area?.box.map((v,i)=>v*(i%2?sy:sx)),points:area?.points.map(p=>[p[0]*sx,p[1]*sy]),radius:brushRadius*(sx+sy)/2}};
 const splitImage=async(method:string)=>{try{const coords=await pixelArea();const id=await startJob(`/projects/${project!.id}/pages/${pageIndex}/layers/${chosen!.id}/split`,{method,fill:method==='backdrop'?'local':fillMode,...(['auto','backdrop'].includes(method)?{}:coords)});if(method!=='brush')pendingPreview.current=id;}catch(e){catchError(e)}};
 useEffect(()=>{if(splitPreview)requestAnimationFrame(()=>document.querySelector<HTMLElement>('.object-preview input,.object-preview button')?.focus())},[splitPreview?.job]);
 const applySplitPreview=async()=>{if(!splitPreview||!previewSelection.length)return;try{await startJob(`/projects/${splitPreview.project}/pages/${splitPreview.page}/layers/${splitPreview.layer}/split-apply`,{preview_job:splitPreview.job,candidate_ids:previewSelection,name:previewName});setSplitPreview(null)}catch(e){catchError(e)}};
 const repairText=async()=>{try{const coords=await pixelArea();if(!coords.box)throw new Error('请先框选需要校正的文字');await startJob(`/projects/${project!.id}/pages/${pageIndex}/layers/${chosen!.id}/text-repair`,{box:coords.box,text:manualText,font_size:manualSize,color:manualColor});}catch(e){catchError(e)}};
 const submitCloud=async()=>{try{const coords=await pixelArea();if(!coords.box||coords.box[2]-coords.box[0]<2||coords.box[3]-coords.box[1]<2)throw new Error('先框选需要发送的局部区域');const id=await startJob(`/projects/${project!.id}/pages/${pageIndex}/cloud`,{provider:cloudProvider,layer_id:chosen!.id,reason:cloudReason,prompt:cloudPrompt,box:coords.box,mask_asset:chosen!.mask});if(cloudProvider==='sam3')pendingPreview.current=id;setCloudOpen(false)}catch(e){catchError(e)}};
 const field=(label:string,key:'x'|'y'|'width'|'height'|'rotation'|'font_size'|'char_spacing')=><label className="number-field">{label}<input type="number" step={key==='rotation'?1:.1} value={chosen?Math.round((chosen[key]||0)*100)/100:0} disabled={disabled||chosen?.locked} onChange={e=>{const v=Number(e.target.value);if(Number.isFinite(v)&&(!['width','height','font_size'].includes(key)||v>0)){if(chosen?.kind==='path'&&(key==='width'||key==='height')){const ratio=v/chosen[key];update({[key]:v,path:chosen.path.map(c=>({...c,points:c.points.map((p,i)=>i%2===(key==='height'?1:0)?p*ratio:p)}))})}else update({[key]:v})}}}/></label>;

